    data=(pathlib.Path('/task')/n).read_bytes()
    assert hashlib.sha256(data).hexdigest()==manifest[n], n
    for r in csv.DictReader(data.decode().splitlines()): rows.append(r)
uniq={}
for r in rows: uniq[r['record_id']]=r
posted={k:r for k,r in uniq.items() if r['status']=='posted'}
